option.value:
table {
    width: 100%;
    border-collapse: collapse;
    table-layout: auto; /* Permite que las columnas se ajusten al texto */
    margin-bottom: 12px;
    font-size: 9px; /* Reduce el tamaño de letra solo dentro de la tabla */
    line-height: 1.2;
}

th, td {
    border: 1px solid #cccccc;
    padding: 4px 5px;
    text-align: left;
    vertical-align: top;
    word-break: normal; /* Evita partir palabras cortas a la mitad */
    overflow-wrap: anywhere; /* Solo rompe cadenas muy largas como URLs o hashes */
}

th {
    background-color: #f4f4f4;
    font-weight: bold;
    white-space: nowrap; /* Mantiene los encabezados en una sola línea */
}

tr {
    page-break-inside: avoid;
}
